#[derive(Clone, Copy)]
enum Swatch {
    Fixed(Color32),
    Brand(BrandStep),
}

impl Swatch {
    const fn resolve(self, brand: &BrandRamp) -> Color32 {
        match self {
            Self::Fixed(color) => color,
            Self::Brand(step) => brand.step(step),
        }
    }
}

